const items = $input.all();
const TYPES = ['pdf','jpg','jpeg','png','heic','webp'];
const filtered = items.filter(item => {
  const mime = item.json.mimeType || '';
  const name = item.json.name || '';
  if (mime === 'application/vnd.google-apps.folder') return false;
  if (TYPES.some(t => mime.includes(t))) return true;
  if (new RegExp(`\\.(${TYPES.join('|')})$`,'i').test(name)) return true;
  return false;
});
const total = filtered.length;
console.log(`GED_MIGRATION: ${total} fichiers à traiter`);
return filtered.map((item, i) => ({
  json: { ...item.json, _batchIndex: i+1, _batchTotal: total }
}));

const bin = $input.first().binary?.data;
if (!bin) throw new Error('Pas de binaire: ' + $input.first().json.name);
return [{ json: { ...$input.first().json }, binary: { data: bin } }];

// ══════════════════════════════════════════════════
// PARSER + ROUTER GED_MIGRATION
// Nœud natif Gemini retourne { text: "..." }
// Rétro-calcul taxes pour AUTONOME
// ══════════════════════════════════════════════════
const item     = $input.first().json;
const fileMeta = $('📦 Préparer Base64').first().json;

// Nœud natif Gemini retourne directement item.text
let rawText = item.text || item.content || '';
if (!rawText) {
  return [{ json: {
    fileId: fileMeta.id||'', fileName: fileMeta.name||'',
    batchIndex: fileMeta._batchIndex||0, batchTotal: fileMeta._batchTotal||0,
    statut: 'ERREUR_IA', Date:'', Emetteur:'', Objet:'', Beneficiaire:'',
    Montant_Net:0, TPS:0, TVQ:0, Montant_Total_TTC:0,
    Categorie:'ERREUR', Sous_Categorie:'', Confiance:'BASSE',
    Mention_Manuscrite:'AUCUNE', Raison_Doute:'Réponse Gemini vide',
    Marchand_Generaliste:'NON', Nom_Fichier_Propose:'', Dossier_Cible:'',
    originalUrl: fileMeta.webViewLink||''
  }}];
}

const cleaned = rawText.replace(/```json/gi,'').replace(/```/g,'').trim();
let p;
try { p = JSON.parse(cleaned); }
catch(e) { p = { Categorie:'ERREUR', Confiance:'BASSE', Raison_Doute:'JSON invalide', Montant_Total_TTC:0 }; }

// Rétro-calcul taxes (AUTONOME uniquement)
const ttc = parseFloat(p.Montant_Total_TTC) || 0;
const cat = (p.Categorie||'').toUpperCase();
let montant_net = 0, montant_tps = 0, montant_tvq = 0;
if (cat === 'AUTONOME' && ttc > 0) {
  montant_net = Math.round((ttc / 1.14975) * 100) / 100;
  montant_tps = Math.round(montant_net * 0.05    * 100) / 100;
  montant_tvq = Math.round(montant_net * 0.09975 * 100) / 100;
}

function sanitize(str) {
  if (!str && str !== 0) return 'INCONNU';
  return String(str).toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9-]/g,'_')
    .replace(/_{2,}/g,'_').replace(/^_+|_+$/g,'').substring(0,40);
}

const FISCAL   = ['PRO','AUTONOME'];
const isFiscal = FISCAL.includes(cat);
let fiscalYear = new Date().getFullYear();
try { if (p.Date) fiscalYear = new Date(p.Date).getFullYear(); } catch(e) {}

const dossierCible = isFiscal ? `Impôts ${fiscalYear}` : '_GED_ARCHIVE';
const date    = p.Date    || 'DATE_INCONNUE';
const montant = String(ttc).replace('.','-');
const nomPropose = [
  date, sanitize(cat), sanitize(p.Emetteur),
  sanitize((p.Sous_Categorie||'')+'_'+(p.Objet||'')),
  sanitize(p.Beneficiaire), montant
].join('-') + '.pdf';

const needsReview = cat === 'MIXTE' || p.Confiance === 'BASSE' || cat === 'ERREUR';

return [{ json: {
  fileId:              fileMeta.id||'',
  fileName:            fileMeta.name||'',
  batchIndex:          fileMeta._batchIndex||0,
  batchTotal:          fileMeta._batchTotal||0,
  statut:              needsReview ? 'A_VALIDER' : 'APPROUVE',
  Date:                p.Date||'',
  Emetteur:            p.Emetteur||'',
  Objet:               p.Objet||'',
  Beneficiaire:        p.Beneficiaire||'',
  Montant_Net:         montant_net,
  TPS:                 montant_tps,
  TVQ:                 montant_tvq,
  Montant_Total_TTC:   ttc,
  Categorie:           p.Categorie||'',
  Sous_Categorie:      p.Sous_Categorie||'',
  Mention_Manuscrite:  p.Mention_Manuscrite||'AUCUNE',
  Confiance:           p.Confiance||'',
  Raison_Doute:        p.Raison_Doute||'',
  Marchand_Generaliste:p.Marchand_Generaliste?'OUI':'NON',
  Nom_Fichier_Propose: nomPropose,
  Dossier_Cible:       dossierCible,
  _isFiscal:           isFiscal,
  _fiscalYear:         fiscalYear,
  originalUrl:         fileMeta.webViewLink||''
}}];

const d = $('📊 Parser + Router').first().json;
const found = $input.first().json;
let folderId;
if (found.files && found.files.length > 0) {
  folderId = found.files[0].id;
} else {
  folderId = d._isFiscal
    ? $env.GED_IMPOTS_PARENT_ID
    : $env.GED_ARCHIVE_FOLDER_ID;
}
return [{ json: { ...d, _resolvedFolderId: folderId } }];

const d   = $('📌 Résoudre Dossier').first().json;
const isAutonome = d.Categorie === 'AUTONOME';
return [{ json: {
  Date:          d.Date||'',
  Emetteur:      d.Emetteur||'',
  Categorie:     d.Categorie||'',
  Sous_Categorie:d.Sous_Categorie||'',
  Objet:         d.Objet||'',
  Beneficiaire:  d.Beneficiaire||'',
  Montant_Net:   isAutonome ? (d.Montant_Net||'') : '',
  TPS:           isAutonome ? (d.TPS||'')         : '',
  TVQ:           isAutonome ? (d.TVQ||'')         : '',
  Montant_TTC:   d.Montant_Total_TTC||'',
  Lien_Drive:    d.originalUrl||'',
  Source:        'GED_MIGRATION'
}}];

const all       = $input.all();
const total     = all.length;
const approuves = all.filter(i => i.json.statut === 'APPROUVE').length;
const aValider  = all.filter(i => i.json.statut === 'A_VALIDER').length;
const erreurs   = all.filter(i => i.json.statut === 'ERREUR_IA').length;
return [{ json: { _resume: { total, approuves, aValider, erreurs } } }];
